import { mkdirSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { base } from "./base";
import { panelBase } from "./panel/base";
import { panelDark } from "./panel/dark";
import { panelLight } from "./panel/light";
import { PANEL_BASE_TOKEN_NAMES, PANEL_THEME_TOKEN_NAMES } from "./panel/types";
import { dark } from "./themes/dark";
import { light } from "./themes/light";
import { BASE_TOKEN_NAMES, THEME_TOKEN_NAMES } from "./types";

const HEADER = `/*
 * GENERATED by @port-watcher/tokens — do not edit by hand.
 * Edit src/base.ts or src/themes/*.ts, then run \`bun run generate\` here.
 * Light is the default in :root; the .dark class re-declares the color tokens.
 */`;

/**
 * Render the tokens stylesheet. `prefix` is prepended to every custom property
 * name — the template ships `mt-` so these never shadow shadcn's own
 * `--background`/`--primary`/… variables; web-ui/styles.css maps shadcn's names
 * to `var(--mt-…)`.
 */
export function generateCss(prefix = "mt-"): string {
  const declare = (name: string, value: string) => `  --${prefix}${name}: ${value};`;

  const rootLines = [
    ...THEME_TOKEN_NAMES.map((name) => declare(name, light[name])),
    ...BASE_TOKEN_NAMES.map((name) => declare(name, base[name])),
  ];
  const darkLines = THEME_TOKEN_NAMES.map((name) => declare(name, dark[name]));

  return [HEADER, "", ":root {", ...rootLines, "}", "", ".dark {", ...darkLines, "}", ""].join(
    "\n",
  );
}

const PANEL_HEADER = `/*
 * GENERATED by @port-watcher/tokens — do not edit by hand.
 * Edit src/panel/*.ts, then run \`bun run generate\` here.
 * Dark is the default in :root. The light set applies to every desktop window
 * (panel, Settings, first-run). \`data-theme\` on <html> forces an appearance;
 * without it the system setting (prefers-color-scheme) decides.
 */`;

/**
 * The menu-bar panel stylesheet: final custom-property names (`--pw-*`, plus the
 * short `--status-danger`, `--radius-*`, `--font-*`), dark by default, light
 * under the system appearance or `data-theme="light"`.
 */
export function generatePanelCss(): string {
  const declare = (indent: string, name: string, value: string) => `${indent}--${name}: ${value};`;
  const dark = (indent: string) =>
    PANEL_THEME_TOKEN_NAMES.map((name) => declare(indent, name, panelDark[name]));
  const light = (indent: string) =>
    PANEL_THEME_TOKEN_NAMES.map((name) => declare(indent, name, panelLight[name]));
  const base = PANEL_BASE_TOKEN_NAMES.map((name) => declare("  ", name, panelBase[name]));

  return [
    PANEL_HEADER,
    "",
    ":root {",
    ...dark("  "),
    ...base,
    "}",
    "",
    "@media (prefers-color-scheme: light) {",
    '  :root:not([data-theme="dark"]) {',
    ...light("    "),
    "  }",
    "}",
    "",
    ':root[data-theme="light"] {',
    ...light("  "),
    "}",
    "",
  ].join("\n");
}

/**
 * Stylesheets from one source:
 *   tokens.css          `--mt-*`, for web-ui — shadcn declares its own
 *                       `--background`/`--primary`, so ours must not collide.
 *   tokens.desktop.css  unprefixed, for consumers with no shadcn in the page
 *                       (the desktop renderer). Shorter to read and to write by hand.
 */
export const OUTPUTS = [
  { file: "tokens.css", prefix: "mt-" },
  { file: "tokens.desktop.css", prefix: "" },
] as const;

/** tokens.panel.css    the desktop menu-bar panel (see `generatePanelCss`). */
export const PANEL_OUTPUT = { file: "tokens.panel.css" } as const;

if (import.meta.main) {
  const outDir = fileURLToPath(new URL("../css/", import.meta.url));
  mkdirSync(outDir, { recursive: true });
  for (const { file, prefix } of OUTPUTS) {
    writeFileSync(`${outDir}${file}`, generateCss(prefix));
    console.log(`Wrote css/${file}`);
  }
  writeFileSync(`${outDir}${PANEL_OUTPUT.file}`, generatePanelCss());
  console.log(`Wrote css/${PANEL_OUTPUT.file}`);
}
